class CircularQueue:
    def __init__(self, size):
        self.size = size
        self.arr = [None] * size
        self.front, self.rear, self.count = 0, -1, 0
    def is_empty(self):
        return self.count == 0
    def is_full(self):
        return self.count == self.size
    def enqueue(self, x):
        if self.is_full():
            return False
        self.rear = (self.rear + 1) % self.size
        self.arr[self.rear] = x
        self.count += 1
        return True
    def dequeue(self):
        if self.is_empty():
            return None
        x = self.arr[self.front]
        self.front = (self.front + 1) % self.size
        self.count -= 1
        return x

